files.content:
.root {
  --vt-surface: #FFFFFF;
  --vt-surface-2: #F9F9F9;
  --vt-surface-deep: #000000;
  --vt-ink: #000000;
  --vt-ink-soft: #717275;
  --vt-on-deep: #FFFFFF;
  --vt-accent: #247cff;
  --vt-on-accent: #000000;
  --vt-accent-ink: #247cff;
  --vt-accent-on-deep: #FFFFFF;
  --vt-line: #eaeaea;

  --h1-font-size: 48px;
  --h2-font-size: 36px;
  --h3-font-size: 32px;
  --h4-font-size: 28px;
  --h5-font-size: 24px;
  --h6-font-size: 22px;
  --p-font-size: 18px;
  --menu-font-size: 16px;

  --font-weight-light: 300;
  --font-weight-normal: 400;
  --font-weight-semibold: 600;
  --font-weight-bold: 700;

  font-family: 'Open Sans', sans-serif;
  background: var(--vt-surface);
  color: var(--vt-ink);
}

.root a {
  touch-action: manipulation;
  transition: all 0.3s;
  color: var(--vt-ink-soft);
  text-decoration: none;
}

.root a:hover {
  color: var(--vt-accent);
}

.root h1,
.root h2,
.root h3,
.root h4,
.root h5,
.root h6 {
  color: var(--vt-ink);
  line-height: inherit;
  font-weight: var(--font-weight-semibold);
}

.root h1,
.root h2 {
  font-weight: var(--font-weight-bold);
}

.root h1 {
  font-size: var(--h1-font-size);
  line-height: normal;
}

.root h2 {
  font-size: var(--h2-font-size);
}

.root h3 {
  font-size: var(--h3-font-size);
}

.root h4 {
  font-size: var(--h4-font-size);
}

.root h5 {
  font-size: var(--h5-font-size);
}

.root h6 {
  font-size: var(--h6-font-size);
}

.root p {
  color: var(--vt-ink-soft);
  font-size: var(--p-font-size);
  font-weight: var(--font-weight-light);
  letter-spacing: 0.5px;
}

.root .sectionPadding {
  padding-top: 7rem;
  padding-bottom: 7rem;
}

/* Navigation */
.nav {
  background: var(--vt-surface);
  padding-top: 20px;
  padding-bottom: 20px;
  box-shadow: 0 0.5rem 1rem rgba(0,0,0,0.05);
}

.navIn {
  display: flex;
  align-items: center;
  justify-content: space-between;
  max-width: 1140px;
  margin: 0 auto;
  padding: 0 15px;
}

.logo {
  display: inline-block;
}

.brand {
  /* Brand component handles its own styling */
}

.navLinks {
  display: flex;
  gap: 2rem;
}

.navLinks a {
  font-weight: var(--font-weight-semibold);
  font-size: var(--menu-font-size);
  padding: 15px 0;
}

.navLinks a:hover,
.navLinks a:focus {
  color: var(--vt-ink);
}

/* Hero */
.hero {
  position: relative;
  padding-top: 0;
}

.heroTrack {
  display: flex;
  overflow-x: auto;
  scroll-snap-type: x mandatory;
  -webkit-overflow-scrolling: touch;
  height: 580px;
}

.heroSlide {
  flex: 0 0 100%;
  scroll-snap-align: start;
}

.heroSlide img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
}

.heroText {
  background: var(--vt-surface);
  position: absolute;
  z-index: 2;
  bottom: 0;
  right: 0;
  padding: 1.5rem 2.5rem;
  width: 50%;
  box-shadow: 0 0.5rem 1rem rgba(0,0,0,0.15);
}

.heroLinks {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 1rem;
}

.customLink {
  display: inline-block;
  text-decoration: none;
  border: 1px solid var(--vt-line);
  color: var(--vt-accent);
  font-weight: var(--font-weight-semibold);
  line-height: 40px;
  padding: 0 30px;
  text-transform: uppercase;
  position: relative;
  overflow: hidden;
  user-select: none;
}

.customLink::before {
  content: attr(data-hover);
  background-color: var(--vt-line);
  color: var(--vt-accent);
  position: absolute;
  top: 100%;
  bottom: 0;
  left: 0;
  transition: all 300ms cubic-bezier(0.19, 1, 0.56, 1);
  right: 0;
  text-align: center;
}

.customLink:hover::before {
  top: 0;
}

.contactPhone {
  font-weight: var(--font-weight-semibold);
}

.phoneIcon {
  /* Placeholder: could use a unicode phone symbol */
}

/* About */
.aboutRow {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
}

.aboutText {
  flex: 0 0 100%;
  max-width: 800px;
}

/* Gallery */
.gallerySection {
  padding: 0;
}

.galleryRow {
  display: flex;
  flex-wrap: wrap;
  margin: 0;
}

.galleryItem {
  flex: 0 0 50%;
  max-width: 50%;
  padding: 0;
}

.galleryItem:first-child {
  padding-right: 0;
}

.galleryItem:last-child {
  padding-left: 0;
}

.galleryImage {
  width: 100%;
  display: block;
}

/* Timeline */
.textCenter {
  text-align: center;
  margin-bottom: 3rem;
}

.timeline {
  position: relative;
}

.timeline::before {
  content: "";
  display: block;
  position: absolute;
  top: 37px;
  left: 50%;
  width: 0;
  border-left: 1px solid var(--vt-line);
  height: 85%;
  z-index: 1;
  transform: translateX(-50%);
}

.timelineNode {
  position: relative;
  display: flex;
  flex-wrap: wrap;
  align-items: flex-start;
  margin-bottom: 2rem;
}

.timelineNode:nth-child(even) {
  flex-direction: row-reverse;
}

.timelineContent {
  position: relative;
  flex: 0 0 45%;
  background: var(--vt-surface);
  box-shadow: 0 0.5rem 1rem rgba(0,0,0,0.15);
  border-radius: 0 0 0.25rem 0.25rem;
  padding: 0;
  z-index: 2;
}

.timelineContent h3 {
  background: var(--vt-surface-deep);
  color: var(--vt-on-deep);
  padding: 10px 30px;
  margin: 0;
  border-radius: 0.25rem 0.25rem 0 0;
  position: relative;
}

.timelineContent p {
  padding: 10px 30px;
  margin: 0;
}

.timelineNode:nth-child(odd) .timelineContent h3,
.timelineNode:nth-child(odd) .timelineContent p {
  text-align: right;
}

.timelineNode:nth-child(odd) .timelineContent h3::after {
  content: "";
  position: absolute;
  top: 50%;
  left: 100%;
  transform: translate(0, -50%);
  width: 0;
  border-left: 10px solid var(--vt-surface-deep);
  border-top: 10px solid transparent;
  border-bottom: 10px solid transparent;
}

.timelineNode:nth-child(even) .timelineContent h3::after {
  content: "";
  position: absolute;
  top: 50%;
  right: 100%;
  transform: translate(0, -50%);
  width: 0;
  border-right: 10px solid var(--vt-surface-deep);
  border-top: 10px solid transparent;
  border-bottom: 10px solid transparent;
}

.timelineIcon {
  flex: 0 0 10%;
  display: flex;
  justify-content: center;
  align-items: center;
  z-index: 10;
}

.timelineIcon::before {
  content: "";
  width: 80px;
  height: 80px;
  border-radius: 50%;
  background: var(--vt-surface);
  box-shadow: 0 1rem 3rem rgba(0,0,0,0.175);
  position: absolute;
  top: 0;
  left: 50%;
  transform: translate(-50%, 0);
}

.timelineIcon span {
  position: relative;
  z-index: 20;
  font-size: var(--h3-font-size);
  color: var(--vt-accent);
  line-height: 80px;
}

.timelineDate {
  flex: 0 0 45%;
  padding: 1rem 0;
  color: var(--vt-ink-soft);
}

.timelineNode:nth-child(odd) .timelineDate {
  text-align: left;
  padding-left: 20px;
}

.timelineNode:nth-child(even) .timelineDate {
  text-align: right;
  padding-right: 20px;
}

/* Contact */
.contactSection {
  overflow-x: hidden; /* Fix for FindUs overflow */
}

/* Footer */
.siteFooter {
  background: var(--vt-surface-2);
  padding-top: 5rem;
  padding-bottom: 5rem;
}

.footerRow {
  display: flex;
  flex-wrap: wrap;
  gap: 2rem;
}

.footerColOpening,
.footerColClinic,
.footerColSocial,
.footerColCopyright {
  flex: 1 1 250px;
}

.footerColCopyright p {
  font-size: var(--menu-font-size);
}

/* Responsive adjustments */
@media screen and (max-width: 991px) {
  .root {
    --h1-font-size: 38px;
    --h2-font-size: 32px;
    --h3-font-size: 26px;
    --h4-font-size: 24px;
    --h5-font-size: 20px;
    --h6-font-size: 18px;
  }

  .root .sectionPadding {
    padding-top: 5rem;
    padding-bottom: 5rem;
  }

  .nav {
    padding-top: 10px;
    padding-bottom: 10px;
  }

  .heroTrack {
    height: auto;
  }

  .heroText {
    position: relative;
    width: auto;
    bottom: auto;
    right: auto;
    margin: -100px 15px 0;
    box-shadow: none;
  }

  .timeline::before {
    left: 33px;
  }

  .timelineNode {
    flex-direction: row;
    margin-left: 60px;
  }

  .timelineNode:nth-child(even) {
    flex-direction: row;
  }

  .timelineContent {
    flex: 1 1 100%;
  }

  .timelineContent h3,
  .timelineContent p {
    text-align: left !important;
  }

  .timelineNode:nth-child(odd) .timelineContent h3::after,
  .timelineNode:nth-child(even) .timelineContent h3::after {
    right: 100%;
    left: auto;
    border-right: 10px solid var(--vt-surface-deep);
    border-left: 0;
    border-top: 10px solid transparent;
    border-bottom: 10px solid transparent;
  }

  .timelineIcon {
    position: absolute;
    left: -40px;
    top: 0;
  }

  .timelineIcon::before {
    width: 75px;
    height: 75px;
  }

  .timelineIcon span {
    line-height: 75px;
  }

  .timelineDate {
    flex: 1 1 100%;
    text-align: left !important;
    padding-left: 20px;
    padding-right: 0;
  }
}

@media screen and (max-width: 767px) {
  .navIn {
    padding: 0 10px;
  }

  .navLinks {
    gap: 1rem;
  }

  .heroText {
    margin: -80px 10px 0;
    padding: 1.5rem;
  }

  .galleryItem {
    flex: 0 0 100%;
    max-width: 100%;
  }
}

@media screen and (max-width: 575px) {
  .timeline::before {
    left: 57px;
  }

  .timelineIcon {
    left: -20px;
  }

  .timelineIcon::before {
    width: 70px;
    height: 70px;
  }

  .timelineIcon span {
    line-height: 70px;
  }
}

@media screen and (max-width: 480px) {
  .heroLinks .customLink {
    font-size: 12px;
    line-height: 30px;
    padding: 0 25px;
  }

  .contactPhone {
    font-size: 12px;
  }
}

.root a:focus-visible {
  outline: 2px solid var(--vt-accent);
  outline-offset: 2px;
}
